+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    @Test
+    void rendersAndSendsInABrowser() {
+        page.navigate(getUrl() + "/contact");
+
+        TextFieldElement.getByLabel(page, "Name").setValue("Browser user");
+        EmailFieldElement.getByLabel(page, "Email").setValue("browser@example.com");
+        TextAreaElement.getByLabel(page, "Message").setValue("Sent from Chromium");
+        ButtonElement send = ButtonElement.getByText(page, "Send");
+        send.click();
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        TextFieldElement.getByLabel(page, "Name").assertValue("");
+        EmailFieldElement.getByLabel(page, "Email").assertValue("");
+        TextAreaElement.getByLabel(page, "Message").assertValue("");
+        send.assertDisabled();
+    }
+}
